INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000900', 'Prinsip utama thermal EOR adalah...', 'The main principle of thermal EOR is...', 'option', 'PFC000000011', 'Inisialisasi', 'a:4:{i:0;s:55:"Memanaskan reservoir untuk menurunkan viskositas minyak";i:1;s:22:"Mendinginkan reservoir";i:2;s:27:"Menambah tekanan overburden";i:3;s:20:"Menurunkan porositas";}', 'a:4:{i:0;s:45:"Heating the reservoir to reduce oil viscosity";i:1;s:21:"Cooling the reservoir";i:2;s:30:"Increasing overburden pressure";i:3;s:17:"Reducing porosity";}', '', 'Memanaskan reservoir untuk menurunkan viskositas minyak', 'Heating the reservoir to reduce oil viscosity', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000901', 'Steam flooding dilakukan dengan cara...', 'Steam flooding is performed by...', 'option', 'PFC000000011', 'Inisialisasi', 'a:4:{i:0;s:27:"Menginjeksikan gas nitrogen";i:1;s:25:"Menginjeksikan air dingin";i:2;s:57:"Menginjeksikan steam secara kontinu melalui sumur injeksi";i:3;s:22:"Menginjeksikan polimer";}', 'a:4:{i:0;s:22:"Injecting nitrogen gas";i:1;s:20:"Injecting cold water";i:2;s:54:"Continuously injecting steam through an injection well";i:3;s:17:"Injecting polymer";}', '', 'Menginjeksikan steam secara kontinu melalui sumur injeksi', 'Continuously injecting steam through an injection well', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000902', 'Cyclic steam stimulation (CSS) juga dikenal sebagai...', 'Cyclic steam stimulation (CSS) is also known as...', 'option', 'PFC000000011', 'Inisialisasi', 'a:4:{i:0;s:3:"WAG";i:1;s:10:"Waterflood";i:2;s:13:"Huff and puff";i:3;s:19:"Surfactant flooding";}', 'a:4:{i:0;s:3:"WAG";i:1;s:10:"Waterflood";i:2;s:13:"Huff and puff";i:3;s:19:"Surfactant flooding";}', '', 'Huff and puff', 'Huff and puff', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000903', 'SAGD menggunakan...', 'SAGD uses...', 'option', 'PFC000000011', 'Inisialisasi', 'a:4:{i:0;s:19:"Satu sumur vertikal";i:1;s:20:"Empat sumur vertikal";i:2;s:48:"Sepasang sumur horizontal (injeksi dan produksi)";i:3;s:32:"Sumur multilateral tanpa injeksi";}', 'a:4:{i:0;s:17:"One vertical well";i:1;s:19:"Four vertical wells";i:2;s:50:"A pair of horizontal wells (injector and producer)";i:3;s:36:"Multilateral wells without injection";}', '', 'Sepasang sumur horizontal (injeksi dan produksi)', 'A pair of horizontal wells (injector and producer)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000904', 'In-situ combustion adalah metode di mana...', 'In-situ combustion is a method where...', 'option', 'PFC000000011', 'Inisialisasi', 'a:4:{i:0;s:20:"Gas dibakar di flare";i:1;s:27:"Air dipanaskan di permukaan";i:2;s:61:"Sebagian minyak dibakar di reservoir untuk menghasilkan panas";i:3;s:32:"Batuan dipanaskan dengan listrik";}', 'a:4:{i:0;s:24:"Gas is burned in a flare";i:1;s:30:"Water is heated at the surface";i:2;s:59:"Part of the oil is burned in the reservoir to generate heat";i:3;s:31:"The rock is heated electrically";}', '', 'Sebagian minyak dibakar di reservoir untuk menghasilkan panas', 'Part of the oil is burned in the reservoir to generate heat', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000905', 'Gas yang paling umum digunakan pada gas EOR untuk pencampuran (miscible) adalah...', 'The gas most commonly used in gas EOR for miscibility is...', 'option', 'PFC000000011', 'Inisialisasi', 'a:4:{i:0;s:3:"CO2";i:1;s:6:"Helium";i:2;s:5:"Argon";i:3;s:5:"Udara";}', 'a:4:{i:0;s:3:"CO2";i:1;s:6:"Helium";i:2;s:5:"Argon";i:3;s:3:"Air";}', '', 'CO2', 'CO2', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000906', 'Injeksi gas dikatakan miscible apabila...', 'Gas injection is said to be miscible when...', 'option', 'PFC000000011', 'Inisialisasi', 'a:4:{i:0;s:32:"Gas dan minyak terpisah sempurna";i:1;s:49:"Gas dan minyak bercampur tanpa tegangan antarmuka";i:2;s:28:"Gas tidak larut dalam minyak";i:3;s:16:"Tidak ada aliran";}', 'a:4:{i:0;s:31:"Gas and oil separate completely";i:1;s:43:"Gas and oil mix without interfacial tension";i:2;s:28:"Gas does not dissolve in oil";i:3;s:16:"There is no flow";}', '', 'Gas dan minyak bercampur tanpa tegangan antarmuka', 'Gas and oil mix without interfacial tension', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000907', 'Manakah yang termasuk metode thermal EOR?', 'Which of the following are thermal EOR methods?', 'multi', 'PFC000000011', 'Inisialisasi', 'a:4:{i:0;s:14:"Steam flooding";i:1;s:24:"Cyclic steam stimulation";i:2;s:18:"In-situ combustion";i:3;s:16:"Polymer flooding";}', 'a:4:{i:0;s:14:"Steam flooding";i:1;s:24:"Cyclic steam stimulation";i:2;s:18:"In-situ combustion";i:3;s:16:"Polymer flooding";}', '', 'a:3:{i:0;s:14:"Steam flooding";i:1;s:24:"Cyclic steam stimulation";i:2;s:18:"In-situ combustion";}', 'a:3:{i:0;s:14:"Steam flooding";i:1;s:24:"Cyclic steam stimulation";i:2;s:18:"In-situ combustion";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000908', 'Urutkan tahapan siklus CSS (cyclic steam stimulation).', 'Arrange the stages of the CSS (cyclic steam stimulation) cycle.', 'drag', 'PFC000000011', 'Inisialisasi', 'a:5:{i:0;s:15:"Injeksi polimer";i:1;s:20:"Injeksi steam (huff)";i:2;s:15:"Periode soaking";i:3;s:15:"Produksi (puff)";i:4;s:29:"Pengulangan siklus berikutnya";}', 'a:5:{i:0;s:17:"Polymer injection";i:1;s:22:"Steam injection (huff)";i:2;s:14:"Soaking period";i:3;s:17:"Production (puff)";i:4;s:28:"Repetition of the next cycle";}', '', 'a:4:{i:0;s:20:"Injeksi steam (huff)";i:1;s:15:"Periode soaking";i:2;s:15:"Produksi (puff)";i:3;s:29:"Pengulangan siklus berikutnya";}', 'a:4:{i:0;s:22:"Steam injection (huff)";i:1;s:14:"Soaking period";i:2;s:17:"Production (puff)";i:3;s:28:"Repetition of the next cycle";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000909', 'Benarkah thermal EOR lebih cocok untuk minyak berat dengan viskositas tinggi?', 'Is it true that thermal EOR is more suitable for heavy oil with high viscosity?', 'yesorno', 'PFC000000011', 'Inisialisasi', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000910', 'Kenaikan suhu reservoir dari 40 C ke 200 C pada minyak berat umumnya menurunkan viskositas hingga...', 'Raising reservoir temperature from 40 C to 200 C in heavy oil generally reduces viscosity by up to...', 'option', 'PFC000000011', 'Final Advanced', 'a:4:{i:0;s:13:"Tidak berubah";i:1;s:12:"Hanya 2 kali";i:2;s:50:"Beberapa orde besaran (ratusan hingga ribuan kali)";i:3;s:20:"Menjadi lebih tinggi";}', 'a:4:{i:0;s:9:"No change";i:1;s:12:"Only 2 times";i:2;s:60:"Several orders of magnitude (hundreds to thousands of times)";i:3;s:15:"Becoming higher";}', '', 'Beberapa orde besaran (ratusan hingga ribuan kali)', 'Several orders of magnitude (hundreds to thousands of times)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000911', 'Steam quality (kualitas steam) menyatakan...', 'Steam quality expresses...', 'option', 'PFC000000011', 'Final Advanced', 'a:4:{i:0;s:10:"Suhu steam";i:1;s:17:"Kecepatan injeksi";i:2;s:13:"Tekanan steam";i:3;s:47:"Fraksi massa steam (uap) dalam campuran uap-air";}', 'a:4:{i:0;s:17:"Steam temperature";i:1;s:14:"Injection rate";i:2;s:14:"Steam pressure";i:3;s:61:"The mass fraction of steam (vapor) in the steam-water mixture";}', '', 'Fraksi massa steam (uap) dalam campuran uap-air', 'The mass fraction of steam (vapor) in the steam-water mixture', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000912', 'Steam-oil ratio (SOR) adalah...', 'The steam-oil ratio (SOR) is...', 'option', 'PFC000000011', 'Final Advanced', 'a:4:{i:0;s:29:"Perbandingan tekanan dan suhu";i:1;s:61:"Volume steam yang diinjeksi per volume minyak yang diproduksi";i:2;s:35:"Perbandingan minyak dan air formasi";i:3;s:27:"Perbandingan gas dan minyak";}', 'a:4:{i:0;s:36:"The ratio of pressure to temperature";i:1;s:55:"The volume of steam injected per volume of oil produced";i:2;s:35:"The ratio of oil to formation water";i:3;s:23:"The ratio of gas to oil";}', '', 'Volume steam yang diinjeksi per volume minyak yang diproduksi', 'The volume of steam injected per volume of oil produced', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000913', 'Minimum miscibility pressure (MMP) adalah tekanan minimum agar...', 'Minimum miscibility pressure (MMP) is the minimum pressure for...', 'option', 'PFC000000011', 'Final Advanced', 'a:4:{i:0;s:12:"Batuan retak";i:1;s:13:"Polimer larut";i:2;s:44:"Gas dan minyak tercampur sempurna (miscible)";i:3;s:12:"Air mendidih";}', 'a:4:{i:0;s:20:"The rock to fracture";i:1;s:19:"Polymer to dissolve";i:2;s:36:"Gas and oil to become fully miscible";i:3;s:13:"Water to boil";}', '', 'Gas dan minyak tercampur sempurna (miscible)', 'Gas and oil to become fully miscible', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000914', 'CO2 miscible flooding umumnya memerlukan tekanan reservoir...', 'CO2 miscible flooding generally requires reservoir pressure...', 'option', 'PFC000000011', 'Final Advanced', 'a:4:{i:0;s:11:"Di atas MMP";i:1;s:12:"Di bawah MMP";i:2;s:28:"Sama dengan tekanan atmosfer";i:3;s:24:"Tidak bergantung tekanan";}', 'a:4:{i:0;s:13:"Above the MMP";i:1;s:13:"Below the MMP";i:2;s:29:"Equal to atmospheric pressure";i:3;s:23:"Independent of pressure";}', '', 'Di atas MMP', 'Above the MMP', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000915', 'Masalah utama injeksi gas pada reservoir minyak adalah...', 'The main problem with gas injection in oil reservoirs is...', 'option', 'PFC000000011', 'Final Advanced', 'a:4:{i:0;s:66:"Viscous fingering dan gravity override akibat mobilitas gas tinggi";i:1;s:17:"Gas terlalu berat";i:2;s:24:"Gas tidak dapat mengalir";i:3;s:31:"Gas menaikkan viskositas minyak";}', 'a:4:{i:0;s:63:"Viscous fingering and gravity override due to high gas mobility";i:1;s:16:"Gas is too heavy";i:2;s:15:"Gas cannot flow";i:3;s:27:"Gas increases oil viscosity";}', '', 'Viscous fingering dan gravity override akibat mobilitas gas tinggi', 'Viscous fingering and gravity override due to high gas mobility', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000916', 'Metode WAG (water alternating gas) dilakukan untuk...', 'The WAG (water alternating gas) method is applied to...', 'option', 'PFC000000011', 'Final Advanced', 'a:4:{i:0;s:24:"Menaikkan viskositas gas";i:1;s:21:"Menambah produksi air";i:2;s:46:"Mengurangi fingering gas dan memperbaiki sweep";i:3;s:28:"Menurunkan tekanan reservoir";}', 'a:4:{i:0;s:22:"Increase gas viscosity";i:1;s:25:"Increase water production";i:2;s:38:"Reduce gas fingering and improve sweep";i:3;s:24:"Lower reservoir pressure";}', '', 'Mengurangi fingering gas dan memperbaiki sweep', 'Reduce gas fingering and improve sweep', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000917', 'Pada in-situ combustion, zona di depan front pembakaran tempat minyak ringan menguap disebut...', 'In in-situ combustion, the zone ahead of the combustion front where light oil vaporizes is called...', 'option', 'PFC000000011', 'Final Advanced', 'a:4:{i:0;s:15:"Zona overburden";i:1;s:29:"Zona distilasi (vaporization)";i:2;s:13:"Zona terbakar";i:3;s:8:"Zona air";}', 'a:4:{i:0;s:15:"Overburden zone";i:1;s:32:"Distillation (vaporization) zone";i:2;s:11:"Burned zone";i:3;s:10:"Water zone";}', '', 'Zona distilasi (vaporization)', 'Distillation (vaporization) zone', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000918', 'Kehilangan panas (heat loss) pada steam flooding terutama terjadi melalui...', 'Heat loss in steam flooding mainly occurs through...', 'option', 'PFC000000011', 'Final Advanced', 'a:4:{i:0;s:18:"Radiasi ke angkasa";i:1;s:41:"Konduksi ke formasi sekitar dan permukaan";i:2;s:17:"Pendinginan pompa";i:3;s:14:"Aliran listrik";}', 'a:4:{i:0;s:20:"Radiation to the sky";i:1;s:52:"Conduction to surrounding formations and the surface";i:2;s:12:"Pump cooling";i:3;s:18:"Electrical current";}', '', 'Konduksi ke formasi sekitar dan permukaan', 'Conduction to surrounding formations and the surface', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000919', 'Injeksi CO2 juga menurunkan viskositas minyak karena...', 'CO2 injection also reduces oil viscosity because...', 'option', 'PFC000000011', 'Final Advanced', 'a:4:{i:0;s:22:"CO2 larut dalam minyak";i:1;s:21:"CO2 membekukan minyak";i:2;s:22:"CO2 mengubah porositas";i:3;s:20:"CO2 menambah lempung";}', 'a:4:{i:0;s:24:"CO2 dissolves in the oil";i:1;s:19:"CO2 freezes the oil";i:2;s:20:"CO2 changes porosity";i:3;s:13:"CO2 adds clay";}', '', 'CO2 larut dalam minyak', 'CO2 dissolves in the oil', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000920', 'Kebutuhan udara (air requirement) pada in-situ combustion dinyatakan sebagai...', 'Air requirement in in-situ combustion is expressed as...', 'option', 'PFC000000011', 'Final Advanced', 'a:4:{i:0;s:24:"Perbandingan gas dan air";i:1;s:15:"Kecepatan kipas";i:2;s:46:"Volume udara per volume minyak yang diproduksi";i:3;s:13:"Tekanan udara";}', 'a:4:{i:0;s:25:"The ratio of gas to water";i:1;s:9:"Fan speed";i:2;s:40:"Volume of air per volume of oil produced";i:3;s:12:"Air pressure";}', '', 'Volume udara per volume minyak yang diproduksi', 'Volume of air per volume of oil produced', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000921', 'Thermal EOR umumnya kurang cocok pada reservoir yang...', 'Thermal EOR is generally less suitable for reservoirs that are...', 'option', 'PFC000000011', 'Final Advanced', 'a:4:{i:0;s:44:"Sangat tipis dengan lapisan overburden tipis";i:1;s:15:"Tebal dan dalam";i:2;s:23:"Mengandung minyak berat";i:3;s:26:"Memiliki viskositas tinggi";}', 'a:4:{i:0;s:32:"Very thin with a thin overburden";i:1;s:14:"Thick and deep";i:2;s:20:"Containing heavy oil";i:3;s:21:"Having high viscosity";}', '', 'Sangat tipis dengan lapisan overburden tipis', 'Very thin with a thin overburden', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000922', 'Manakah faktor yang memengaruhi kelayakan steam flooding?', 'Which factors affect the feasibility of steam flooding?', 'multi', 'PFC000000011', 'Final Advanced', 'a:4:{i:0;s:12:"Warna batuan";i:1;s:41:"Kedalaman reservoir (tekanan hidrostatik)";i:2;s:19:"Ketebalan reservoir";i:3;s:36:"Viskositas minyak dan kualitas steam";}', 'a:4:{i:0;s:10:"Rock color";i:1;s:38:"Reservoir depth (hydrostatic pressure)";i:2;s:19:"Reservoir thickness";i:3;s:31:"Oil viscosity and steam quality";}', '', 'a:3:{i:0;s:41:"Kedalaman reservoir (tekanan hidrostatik)";i:1;s:19:"Ketebalan reservoir";i:2;s:36:"Viskositas minyak dan kualitas steam";}', 'a:3:{i:0;s:38:"Reservoir depth (hydrostatic pressure)";i:1;s:19:"Reservoir thickness";i:2;s:31:"Oil viscosity and steam quality";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000923', 'Manakah mekanisme peningkatan perolehan pada injeksi CO2?', 'Which are oil recovery mechanisms in CO2 injection?', 'multi', 'PFC000000011', 'Final Advanced', 'a:4:{i:0;s:39:"Pencampuran (miscibility) dengan minyak";i:1;s:27:"Penurunan viskositas minyak";i:2;s:29:"Peningkatan tekanan reservoir";i:3;s:29:"Peningkatan viskositas minyak";}', 'a:4:{i:0;s:20:"Miscibility with oil";i:1;s:26:"Reduction of oil viscosity";i:2;s:30:"Increase in reservoir pressure";i:3;s:25:"Increase in oil viscosity";}', '', 'a:3:{i:0;s:39:"Pencampuran (miscibility) dengan minyak";i:1;s:27:"Penurunan viskositas minyak";i:2;s:29:"Peningkatan tekanan reservoir";}', 'a:3:{i:0;s:20:"Miscibility with oil";i:1;s:26:"Reduction of oil viscosity";i:2;s:30:"Increase in reservoir pressure";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000924', 'Manakah tantangan operasional in-situ combustion?', 'Which are operational challenges of in-situ combustion?', 'multi', 'PFC000000011', 'Final Advanced', 'a:4:{i:0;s:32:"Peningkatan porositas berlebihan";i:1;s:27:"Risiko ledakan di permukaan";i:2;s:29:"Kualitas gas buang dan korosi";i:3;s:30:"Kontrol front pembakaran sulit";}', 'a:4:{i:0;s:27:"Excessive porosity increase";i:1;s:22:"Surface explosion risk";i:2;s:33:"Exhaust gas quality and corrosion";i:3;s:41:"Difficult control of the combustion front";}', '', 'a:3:{i:0;s:30:"Kontrol front pembakaran sulit";i:1;s:27:"Risiko ledakan di permukaan";i:2;s:29:"Kualitas gas buang dan korosi";}', 'a:3:{i:0;s:41:"Difficult control of the combustion front";i:1;s:22:"Surface explosion risk";i:2;s:33:"Exhaust gas quality and corrosion";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000925', 'Manakah pernyataan yang benar tentang gas EOR?', 'Which statements about gas EOR are correct?', 'multi', 'PFC000000011', 'Final Advanced', 'a:4:{i:0;s:54:"Gas memiliki mobilitas tinggi sehingga mudah fingering";i:1;s:45:"MMP bergantung pada komposisi minyak dan suhu";i:2;s:37:"WAG digunakan untuk memperbaiki sweep";i:3;s:41:"Gas selalu meningkatkan viskositas minyak";}', 'a:4:{i:0;s:42:"Gas has high mobility so it fingers easily";i:1;s:46:"MMP depends on oil composition and temperature";i:2;s:28:"WAG is used to improve sweep";i:3;s:34:"Gas always increases oil viscosity";}', '', 'a:3:{i:0;s:54:"Gas memiliki mobilitas tinggi sehingga mudah fingering";i:1;s:45:"MMP bergantung pada komposisi minyak dan suhu";i:2;s:37:"WAG digunakan untuk memperbaiki sweep";}', 'a:3:{i:0;s:42:"Gas has high mobility so it fingers easily";i:1;s:46:"MMP depends on oil composition and temperature";i:2;s:28:"WAG is used to improve sweep";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000926', 'Urutkan zona in-situ combustion dari sumur injeksi ke arah depan.', 'Arrange the in-situ combustion zones from the injection well outward.', 'drag', 'PFC000000011', 'Final Advanced', 'a:5:{i:0;s:13:"Zona terbakar";i:1;s:14:"Zona distilasi";i:2;s:23:"Zona kondensasi uap air";i:3;s:27:"Zona minyak tak terpanaskan";i:4;s:16:"Zona air formasi";}', 'a:5:{i:0;s:11:"Burned zone";i:1;s:17:"Distillation zone";i:2;s:23:"Steam condensation zone";i:3;s:17:"Unheated oil zone";i:4;s:20:"Formation water zone";}', '', 'a:4:{i:0;s:13:"Zona terbakar";i:1;s:14:"Zona distilasi";i:2;s:23:"Zona kondensasi uap air";i:3;s:27:"Zona minyak tak terpanaskan";}', 'a:4:{i:0;s:11:"Burned zone";i:1;s:17:"Distillation zone";i:2;s:23:"Steam condensation zone";i:3;s:17:"Unheated oil zone";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000927', 'Urutkan tahapan siklus WAG.', 'Arrange the WAG cycle stages.', 'drag', 'PFC000000011', 'Final Advanced', 'a:5:{i:0;s:11:"Injeksi gas";i:1;s:11:"Injeksi air";i:2;s:16:"Periode produksi";i:3;s:18:"Pengulangan siklus";i:4;s:17:"Injeksi surfaktan";}', 'a:5:{i:0;s:13:"Gas injection";i:1;s:15:"Water injection";i:2;s:17:"Production period";i:3;s:16:"Cycle repetition";i:4;s:20:"Surfactant injection";}', '', 'a:4:{i:0;s:11:"Injeksi gas";i:1;s:11:"Injeksi air";i:2;s:16:"Periode produksi";i:3;s:18:"Pengulangan siklus";}', 'a:4:{i:0;s:13:"Gas injection";i:1;s:15:"Water injection";i:2;s:17:"Production period";i:3;s:16:"Cycle repetition";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000928', 'Benarkah steam flooding pada reservoir yang sangat dalam menjadi kurang efisien karena kehilangan panas dan tekanan hidrostatik tinggi?', 'Is it true that steam flooding in very deep reservoirs becomes less efficient due to heat loss and high hydrostatic pressure?', 'yesorno', 'PFC000000011', 'Final Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
